const event=$input.first().json||{};
const execution=event.execution||{};
const workflow=event.workflow||{};
const executionId=String(execution.id||event.executionId||'').trim();
const workflowName=String(workflow.name||event.workflowName||'').toUpperCase();
const mapping=[
  ['WF01','lead-qualification'],
  ['WF08','UC10_DATA_CLEANING'],
  ['WF10','T12-WF10_NEXT_BEST_ACTION'],
  ['WF11','T12-WF11_SALES_MEETING'],
  ['WF12','T12-WF12_QUOTE_PROPOSAL']
];
const selected=mapping.find(([marker])=>workflowName.includes(marker));
if(!executionId||!selected)throw new Error('Cannot map Error Trigger event to an allowlisted T12 workflow');

const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
function findWorkflowRunId(value,depth=0){
  if(depth>12||value===null||value===undefined)return null;
  if(Array.isArray(value)){
    for(const item of value){const found=findWorkflowRunId(item,depth+1);if(found)return found;}
    return null;
  }
  if(typeof value!=='object')return null;
  if(typeof value.workflowRunId==='string'&&uuid.test(value.workflowRunId))return value.workflowRunId;
  for(const child of Object.values(value)){const found=findWorkflowRunId(child,depth+1);if(found)return found;}
  return null;
}
const workflowRunId=findWorkflowRunId(execution.data) || findWorkflowRunId(event.data);
const rawMessage=String(execution.error?.message||event.error?.message||'').toLowerCase();
let errorCategory='WORKFLOW_EXECUTION_FAILED';
if(rawMessage.includes('timeout')||rawMessage.includes('timed out'))errorCategory='UPSTREAM_TIMEOUT';
else if(rawMessage.includes('429')||rawMessage.includes('rate limit'))errorCategory='UPSTREAM_RATE_LIMIT';
else if(rawMessage.includes('401')||rawMessage.includes('403')||rawMessage.includes('unauthorized'))errorCategory='UPSTREAM_AUTH_FAILURE';
else if(rawMessage.includes('validation')||rawMessage.includes('invalid'))errorCategory='INVALID_INPUT';
const failedNodeName=String(execution.lastNodeExecuted||event.lastNodeExecuted||'unknown').replace(/[\r\n]/g,' ').slice(0,120);
return [{json:{
  workflowRunId:workflowRunId||undefined,
  workflowName:selected[1],
  n8nExecutionId:executionId,
  errorCategory,
  failedNodeName
}}];
